@Override
protected Object visit(ASTReference node, Object data) {
    if (isCancelled()) {
        throw new JexlException.Cancel(node);
    }

    final int numChildren = node.jjtGetNumChildren();
    Object object = null;
    StringBuilder ant = new StringBuilder();

    for (int c = 0; c < numChildren; c++) {
        JexlNode objectNode = node.jjtGetChild(c);

        if (objectNode instanceof ASTMethodNode && object == null) {
            break; // Stop the loop if ASTMethodNode encountered and object is null
        }

        Object result = objectNode.jjtAccept(this, data);
        if (result != null) {
            object = result;
        } else {
            if (object == null) {
                if (objectNode instanceof ASTIdentifier && ((ASTIdentifier) objectNode).getSymbol() < 0) {
                    ant.append(((ASTIdentifier) objectNode).getName());
                } else {
                    break; // Stop the loop if object is still null and node is not an identifier with negative symbol
                }
            } else {
                if (objectNode instanceof ASTIdentifierAccess) {
                    ant.append('.');
                    ant.append(((ASTIdentifierAccess) objectNode).getName());
                } else {
                    break; // Stop the loop if node is not an ASTIdentifierAccess
                }
            }
            object = context.get(ant.toString());
        }
    }

    if (object == null && ant.length() > 0 && !isTernaryProtected(node)) {
        boolean undefined = !(context.has(ant.toString()) || isLocalVariable(node, 0));
        return unsolvableVariable(node, ant.toString(), undefined);
    }

    return object;
}

